import java.util.*;

class Solution {
    public int longestConsecutive(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            set.add(num);
        }
        int result = 0;
        for (int num : set) {
            if (set.contains(num - 1)) { // 只从每段的起点开始，避免重复扫描
                continue;
            }
            int current = num;
            int length = 1;
            while (set.contains(current + 1)) {
                current++;
                length++;
            }
            result = Math.max(result, length);
        }
        return result;
    }
}

