class Solution {
    public int maxArea(int[] height) {
        int left = 0;
        int right = height.length - 1;
        int result = 0;
        while (left < right) {
            int area = Math.min(height[left], height[right]) * (right - left);
            result = Math.max(result, area);
            if (height[left] <= height[right]) { // 保留短板只会让宽度变小，移动短板才可能改善
                left++;
            } else {
                right--;
            }
        }
        return result;
    }
}

