import java.util.*;

class Solution {
    public int subarraySum(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        count.put(0, 1); // 空前缀，让从下标0开始的区间也能被统计
        int sum = 0;
        int result = 0;
        for (int num : nums) {
            sum += num;
            result += count.getOrDefault(sum - k, 0); // 先查之前的前缀，避免把空区间计入
            count.put(sum, count.getOrDefault(sum, 0) + 1);
        }
        return result;
    }
}

